#!/usr/bin/env node
/**
 * Coverage report utility for CI and local developer workflows.
 *
 * Responsibilities:
 * - Parse LCOV output generated by `bun test --coverage`
 * - Enforce minimum line coverage threshold
 * - Render markdown summaries for GitHub job summaries
 */

import { readFileSync } from "node:fs";

/**
 * @typedef {object} CliArgs
 * @property {string} lcov
 * @property {number} minLines
 * @property {boolean} summaryMd
 */

/**
 * @typedef {object} CoverageFileEntry
 * @property {string} file
 * @property {number} linesFound
 * @property {number} linesHit
 */

/**
 * @typedef {object} CoverageReport
 * @property {CoverageFileEntry[]} files
 * @property {number} totalFound
 * @property {number} totalHit
 * @property {number} lineCoverage
 */

/**
 * Parses CLI arguments.
 *
 * @param {string[]} argv - Process arguments.
 * @returns {CliArgs} Parsed arguments.
 */
function parseArgs(argv) {
  /** @type {CliArgs} */
  const args = { lcov: "coverage/lcov.info", minLines: 95, summaryMd: false };

  for (let i = 2; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--lcov") {
      if (!argv[i + 1]) throw new Error("Missing value for --lcov");
      args.lcov = argv[i + 1];
      i += 1;
    } else if (arg === "--min-lines") {
      if (!argv[i + 1]) throw new Error("Missing value for --min-lines");
      args.minLines = Number(argv[i + 1]);
      i += 1;
    } else if (arg === "--summary-md") {
      args.summaryMd = true;
    } else if (arg === "--help" || arg === "-h") {
      printHelp();
      process.exit(0);
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  if (!Number.isFinite(args.minLines) || args.minLines < 0 || args.minLines > 100) {
    throw new Error(`Invalid --min-lines value: ${String(args.minLines)} (expected 0-100)`);
  }

  return args;
}

/**
 * Parses LCOV text into aggregate and per-file counters.
 *
 * @param {string} text - Raw LCOV file contents.
 * @returns {CoverageReport} Parsed report.
 */
function parseLcov(text) {
  const lines = text.split(/\r?\n/);
  /** @type {CoverageFileEntry[]} */
  const files = [];
  /** @type {CoverageFileEntry | null} */
  let current = null;

  for (const line of lines) {
    if (line.startsWith("SF:")) {
      current = {
        file: line.slice(3),
        linesFound: 0,
        linesHit: 0,
      };
      files.push(current);
      continue;
    }
    if (!current) continue;
    if (line.startsWith("LF:")) current.linesFound = Number(line.slice(3)) || 0;
    if (line.startsWith("LH:")) current.linesHit = Number(line.slice(3)) || 0;
    if (line === "end_of_record") current = null;
  }

  const totalFound = files.reduce((sum, f) => sum + f.linesFound, 0);
  const totalHit = files.reduce((sum, f) => sum + f.linesHit, 0);
  const lineCoverage = totalFound === 0 ? 100 : (totalHit / totalFound) * 100;

  files.sort((a, b) => {
    const aPct = a.linesFound === 0 ? 100 : (a.linesHit / a.linesFound) * 100;
    const bPct = b.linesFound === 0 ? 100 : (b.linesHit / b.linesFound) * 100;
    return aPct - bPct;
  });

  return { files, totalFound, totalHit, lineCoverage };
}

/**
 * Computes a fixed 2-decimal percentage.
 *
 * @param {number} hit
 * @param {number} found
 * @returns {string}
 */
function pct(hit, found) {
  return (found === 0 ? 100 : (hit / found) * 100).toFixed(2);
}

/**
 * Prints usage information.
 */
function printHelp() {
  console.log("Usage: node scripts/coverage-check.mjs [options]");
  console.log("");
  console.log("Options:");
  console.log("  --lcov <path>       Path to LCOV file (default: coverage/lcov.info)");
  console.log("  --min-lines <num>   Minimum line coverage percent (default: 95)");
  console.log("  --summary-md        Emit GitHub-friendly markdown summary");
  console.log("  -h, --help          Show this help message");
}

try {
  const args = parseArgs(process.argv);
  const lcovText = readFileSync(args.lcov, "utf8");
  const report = parseLcov(lcovText);

  if (args.summaryMd) {
    console.log("## Coverage Summary");
    console.log("");
    console.log(
      `- Line coverage: **${pct(report.totalHit, report.totalFound)}%** (${report.totalHit}/${report.totalFound})`,
    );
    console.log(`- Threshold: **${args.minLines.toFixed(2)}%**`);
    console.log("");
    console.log("### Lowest-Coverage Files");
    console.log("");
    console.log("| File | Line Coverage | Hit/Found |");
    console.log("| --- | ---: | ---: |");
    for (const f of report.files.slice(0, 10)) {
      console.log(
        `| ${f.file} | ${pct(f.linesHit, f.linesFound)}% | ${f.linesHit}/${f.linesFound} |`,
      );
    }
  }

  const coverage = Number(pct(report.totalHit, report.totalFound));
  if (coverage < args.minLines) {
    console.error(
      `Coverage check failed: ${coverage.toFixed(2)}% < ${args.minLines.toFixed(2)}% (lines)`,
    );
    process.exit(1);
  }

  if (!args.summaryMd) {
    console.log(
      `Coverage check passed: ${coverage.toFixed(2)}% >= ${args.minLines.toFixed(2)}% (lines)`,
    );
  }
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`Coverage utility failed: ${message}`);
  process.exit(1);
}
